function LengthOfLongestSubstring(s: string) -> int {
  let chars = s.chars();
  let n = chars.length();
  let last: map<string, int> = {};
  let best = 0;
  let start = 0;
  let i = 0;
  while (i < n) {
    let c = chars[i];
    let seen = last.get(c);
    if (seen != null) {
      if (seen >= start) {
        start = seen + 1;
      }
    }
    last.set(c, i);
    let len = i - start + 1;
    if (len > best) {
      best = len;
    }
    i += 1;
  }
  return best;
}
